private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    // Make sure there is at least one byte to read
    if (!bb.hasRemaining()) {
        return i;
    }
    int b0 = bb.get() & 0xFF;
    int codePoint;
    int additionalBytes = 0;

    if ((b0 & 0x80) == 0) {
        // 1-byte sequence
        codePoint = b0;
    } else if ((b0 & 0xE0) == 0xC0) {
        // 2-byte sequence
        codePoint = b0 & 0x1F;
        additionalBytes = 1;
    } else if ((b0 & 0xF0) == 0xE0) {
        // 3-byte sequence
        codePoint = b0 & 0x0F;
        additionalBytes = 2;
    } else if ((b0 & 0xF8) == 0xF0) {
        // 4-byte sequence
        codePoint = b0 & 0x07;
        additionalBytes = 3;
    } else {
        // Invalid leading byte; ignore and move on
        return i + 1;
    }

    try {
        for (int j = 0; j < additionalBytes; j++) {
            if (!bb.hasRemaining()) {
                // Unterminated sequence; abort
                return i + 1;
            }
            int b = bb.get() & 0x3F;
            codePoint = (codePoint << 6) | b;
        }
    } catch (Exception e) {
        // Any ByteBuffer read error; return the current index
        return i + 1;
    }

    // Append the decoded code point to the StringBuilder
    if (codePoint <= 0xFFFF) {
        sb.append((char) codePoint);
        i += 1;
    } else {
        // Encode as surrogate pair
        int temp = codePoint - 0x10000;
        char high = (char) (0xD800 + (temp >> 10));
        char low = (char) (0xDC00 + (temp & 0x3FF));
        sb.append(high).append(low);
        i += 2;
    }

    return i;
}

