        return -1;
    }
    int length = headerPart.length();
    int start = Math.max(0, end + 1);
    if (start >= length){
        return -1;
    }
    for (int i = start; i < length - 1; i++){
        char c = headerPart.charAt(i);
        if (c == '\r' && headerPart.charAt(i + 1) == '\n'){
            return i;
        }
    }
    return -1;
}

