@Override public void generateGraph(Graph<V,E> target, Map<String,V> resultMap){
    if (target == null || resultMap == null) {
        return;
    }
    // Create and add all vertices to the graph
    List<V> vertices = new ArrayList<>(resultMap.values());
    for (V vertex : vertices) {
        if (!target.containsVertex(vertex)) {
            target.addVertex(vertex);
        }
    }
    // Partition vertices into two halves to form a bipartite graph
    int size = vertices.size();
    int split = size / 2; // left side: 0..split-1, right side: split..size-1
    for (int i = 0; i < split; i++) {
        V left = vertices.get(i);
        for (int j = split; j < size; j++) {
            V right = vertices.get(j);
            if (!target.containsEdge(left, right)) {
                target.addEdge(left, right);
            }
        }
    }
}

