public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    // Compute the size of the serialized message
    int size = schema.getMessageSize(message);
    // Calculate how many bytes the length prefix will occupy (in varint32 format)
    int lengthPrefixSize = CodedOutputStream.computeInt32SizeNoTag(size);
    // Create a CodedOutputStream that is guaranteed to be large enough
    CodedOutputStream cos = CodedOutputStream.newInstance(out, size + lengthPrefixSize);
    // Write the length prefix
    cos.writeRawVarint32(size);
    // Serialize the actual message
    schema.writeTo(message, cos);
    cos.flush();
    return size;
}

