public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }
    ParameterizedType ptype = (ParameterizedType) genericType;
    Type[] typeArgs = ptype.getActualTypeArguments();
    Class<?>[] result = new Class<?>[typeArgs.length];
    for (int i = 0; i < typeArgs.length; i++) {
        Type t = typeArgs[i];
        if (t instanceof Class) {
            result[i] = (Class<?>) t;
        } else if (t instanceof ParameterizedType) {
            result[i] = (Class<?>) ((ParameterizedType) t).getRawType();
        } else if (t instanceof TypeVariable) {
            // Attempt to resolve the type variable using the target type hierarchy
            TypeVariable<?> tv = (TypeVariable<?>) t;
            try {
                // Check generic interfaces
                for (Type iface : targetType.getGenericInterfaces()) {
                    if (iface instanceof ParameterizedType) {
                        ParameterizedType ip = (ParameterizedType) iface;
                        TypeVariable<?>[] ipTvs = ((Class<?>) ip.getRawType()).getTypeParameters();
                        Type[] ipActuals = ip.getActualTypeArguments();
                        for (int j = 0; j < ipTvs.length && j < ipActuals.length; j++) {
                            if (ipTvs[j].equals(tv)) {
                                Type actual = ipActuals[j];
                                if (actual instanceof Class) {
                                    result[i] = (Class<?>) actual;
                                    break;
                                }
                            }
                        }
                    }
                }
                // If not resolved, check superclass
                if (result[i] == null) {
                    Type superType = targetType.getGenericSuperclass();
                    if (superType instanceof ParameterizedType) {
                        ParameterizedType sp = (ParameterizedType) superType;
                        TypeVariable<?>[] spTvs = ((Class<?>) sp.getRawType()).getTypeParameters();
                        Type[] spActuals = sp.getActualTypeArguments();
                        for (int j = 0; j < spTvs.length && j < spActuals.length; j++) {
                            if (spTvs[j].equals(tv)) {
                                Type actual = spActuals[j];
                                if (actual instanceof Class) {
                                    result[i] = (Class<?>) actual;
                                    break;
                                }
                            }
                        }
                    }
                }
            } catch (Exception e) {
                return null;
            }
            if (result[i] == null) {
                return null; // unresolved type variable
            }
        } else {
            return null; // unsupported type argument
        }
    }
    return result;
}

@Override
public void accept(final METRICS data) {
    if (data == null) {
        return;
    }
    // Assume a Map<METRICS, METRICS> named 'cache' is defined in the enclosing class.
    METRICS existing = cache.putIfAbsent(data, data);
    if (existing != null) {
        // Try to merge using a merge(...) method if the METRICS type provides one.
        try {
            java.lang.reflect.Method mergeMethod = existing.getClass()
                                                         .getMethod("merge", data.getClass());
            mergeMethod.invoke(existing, data);
        } catch (Exception ignored) {
            // If no merge method exists, fall back to replacing the old value.
            cache.put(data, data);
        }
    }
}

