protected List<TimeRange> buildTimeRanges(long start,long end){
    if(start < 0 || end < 0){
        throw new IllegalArgumentException("Start and end times must be non-negative");
    }
    if(start > end){
        return java.util.Collections.emptyList();
    }
    java.util.List<TimeRange> ranges = new java.util.ArrayList<>();
    long step = FETCH_DATA_DURATION;
    if(step <= 0){
        ranges.add(new TimeRange(start, end));
        return ranges;
    }
    while(start < end){
        long next = start + step;
        if(next > end){
            next = end;
        }
        ranges.add(new TimeRange(start, next));
        start = next;
    }
    return ranges;
}

