static long compressTimeBucket(long timeBucket,int dayStep){
    try{
        if(dayStep<=0) throw new IllegalArgumentException("dayStep must be positive");
        long year = timeBucket/10000;
        long month = (timeBucket/100)%100;
        int day = (int)(timeBucket%100);
        if(month<1||month>12) throw new IllegalArgumentException("Invalid month");
        if(day<1||day>31) throw new IllegalArgumentException("Invalid day");
        int bucketStart = ((day-1)/dayStep)*dayStep + 1;
        return year*10000 + month*100 + bucketStart;
    }catch(Exception e){
        return 0;
    }
}

public static int computeUTF8Size(final CharSequence str,final int index,final int len){
    if (str == null) {
        throw new IllegalArgumentException("The input string must not be null");
    }
    final int totalLength = str.length();
    if (index < 0 || len < 0 || index > totalLength || index + len > totalLength) {
        throw new IllegalArgumentException("Index or length is out of bounds");
    }
    int size = 0;
    int i = index;
    final int end = index + len;
    while (i < end) {
        char ch = str.charAt(i);
        if (ch <= 0x7F) {
            // ASCII
            size += 1;
            i += 1;
        } else if (ch <= 0x7FF) {
            // 2-byte sequence
            size += 2;
            i += 1;
        } else if (Character.isHighSurrogate(ch)) {
            // surrogate pair -> 4 bytes
            if (i + 1 < end && Character.isLowSurrogate(str.charAt(i + 1))) {
                size += 4;
                i += 2;
            } else {
                throw new IllegalArgumentException("Unpaired high surrogate at index " + i);
            }
        } else if (Character.isLowSurrogate(ch)) {
            // low surrogate without preceding high surrogate
            throw new IllegalArgumentException("Unpaired low surrogate at index " + i);
        } else {
            // 3-byte sequence
            size += 3;
            i += 1;
        }
    }
    return size;
}

