public static String sub(String str,int start,int end){
    if (str == null) {
        return null;
    }
    int len = str.length();
    // Clamp start and end to valid bounds
    if (start < 0) {
        start = 0;
    }
    if (end > len) {
        end = len;
    }
    if (start > len) {
        // start beyond string length => empty substring
        return "";
    }
    if (end <= start) {
        // empty range
        return "";
    }
    try {
        return str.substring(start, end);
    } catch (Exception e) {
        // Fallback: return null or empty string
        return "";
    }
}

public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    if (byteLength < 0) {
        throw new IllegalArgumentException("byteLength must be non-negative");
    }
    int newLen = this.len + byteLength;
    if (buf.length < newLen) {
        int newCap = Math.max(buf.length * 2, newLen);
        byte[] newBuf = new byte[newCap];
        System.arraycopy(buf, 0, newBuf, 0, len);
        buf = newBuf;
    }
    if (byteArrayValue == null) {
        java.util.Arrays.fill(buf, len, newLen, (byte) 0);
    } else {
        if (byteOffset < 0 || byteOffset + byteLength > byteArrayValue.length) {
            throw new IndexOutOfBoundsException();
        }
        System.arraycopy(byteArrayValue, byteOffset, buf, len, byteLength);
    }
    this.len = newLen;
    return this;
}

