public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (str == null || lb == null) {
        return lb;
    }
    try {
        // Convert the CharSequence to UTF-8 byte array
        byte[] bytes = str.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8);
        // Ensure the buffer has enough capacity and put the bytes into it
        lb.put(bytes, 0, bytes.length);
    } catch (RuntimeException ex) {
