        throw new RuntimeException("Failed to write UTF-8 bytes to LinkedBuffer", ex);
    }
    return lb;
}

public void removeFromTreeEdgeList(){
    // Remove from the first doubly‑linked list (e.g. the adjacency list)
    if (prev != null) {
        prev.next = this.next;
    }
    if (next != null) {
        next.prev = this.prev;
    }
    // Remove from the second doubly‑linked list (e.g. the global tree‑edge list)
    if (treePrev != null) {
        treePrev.treeNext = this.treeNext;
    }
    if (treeNext != null) {
        treeNext.treePrev = this.treePrev;
    }
    // Clean up this edge’s own references
    prev = null;
    next = null;
    treePrev = null;
    treeNext = null;
}

public static String findAndSubst(String key, Properties props) {
    if (key == null || props == null) {
        return null;
    }
    String value = props.getProperty(key);
    if (value == null) {
        return null;
    }
    String result = value;
    Pattern pattern = Pattern.compile("\\$\\{([^}]+)\\}");
    // Limit iterations to prevent infinite loops in case of circular references
    int maxIterations = 10;
    while (maxIterations-- > 0) {
        Matcher m = pattern.matcher(result);
        boolean found = false;
        StringBuffer sb = new StringBuffer();
        while (m.find()) {
            found = true;
            String var = m.group(1);
            String sub = props.getProperty(var);
            if (sub == null) {
                // Leave the placeholder unchanged if property not found
                m.appendReplacement(sb, Matcher.quoteReplacement(m.group(0)));
            } else {
                // Replace with the property value, escaping to avoid regex issues
                m.appendReplacement(sb, Matcher.quoteReplacement(sub));
            }
        }
        m.appendTail(sb);
        result = sb.toString();
        if (!found) {
            break;
        }
    }
    return result;
}

