public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> segments = new ArrayList<>();
    if (u == null) {
        return segments;
    }
    String path = u.getPath();
    if (path == null || path.isEmpty()) {
        return segments;
    }
    // Remove leading '/' for absolute paths, as it is not a delimiter
    if (path.startsWith("/")) {
        path = path.substring(1);
    }
    if (path.isEmpty()) {
        return segments;
    }
    String[] parts = path.split("/");
    for (String part : parts) {
        if (part.isEmpty()) {
            continue;
        }
        String decoded = part;
        if (decode) {
            try {
                decoded = java.net.URLDecoder.decode(part, "UTF-8");
            } catch (Exception e) {
                // If decoding fails, fall back to the original part
                decoded = part;
            }
        }
        // Assume PathSegmentImpl has a constructor that accepts a decoded string
        segments.add(new PathSegmentImpl(decoded));
    }
    return segments;
}

