public long readRawVarint64() throws IOException {
    int shift = 0;
    long result = 0;
    while (shift < 64) {
        int b = input.read();
        if (b == -1) {
            throw new EOFException("Reached end of stream while parsing a varint");
        }
        result |= (long) (b & 0x7F) << shift;
        if ((b & 0x80) == 0) {
            return result;
        }
        shift += 7;
    }
    throw new IOException("Varint too long");
}

