private void pop(final String descriptor) {
    try {
        int pos = descriptor.charAt(0) == '(' ? 1 : 0;
        boolean isMethod = descriptor.charAt(0) == '(';

        if (!isMethod) {
            char c = descriptor.charAt(pos);
            switch (c) {
                case 'B':
                case 'C':
                case 'F':
                case 'I':
                case 'S':
                case 'Z':
                    popOperand();
                    return;
                case 'J':
                case 'D':
                    popOperand();
                    popOperand();
                    return;
                case 'L':
                    int endL = descriptor.indexOf(';', pos);
                    if (endL == -1) throw new IllegalArgumentException("Missing ';' in object type");
                    // skip to after ';'
                    popOperand();
                    return;
                case '[':
                    // consume array descriptors
                    while (descriptor.charAt(pos) == '[') pos++;
                    if (descriptor.charAt(pos) == 'L') {
                        int endArrayObj = descriptor.indexOf(';', pos);
                        if (endArrayObj == -1) throw new IllegalArgumentException("Missing ';' in array object");
                    } else {
                        // primitive array element
                    }
                    popOperand();
                    return;
                default:
                    throw new IllegalArgumentException("Unknown type descriptor: " + c);
            }
        }

        // Method descriptor: parse arguments until ')'
        while (pos < descriptor.length() && descriptor.charAt(pos) != ')') {
            char c = descriptor.charAt(pos);
            switch (c) {
                case 'B':
                case 'C':
                case 'F':
                case 'I':
                case 'S':
                case 'Z':
                    popOperand();
                    pos++;
                    break;
                case 'J':
                case 'D':
                    popOperand();
                    popOperand();
                    pos++;
                    break;
                case 'L':
                    int end = descriptor.indexOf(';', pos);
                    if (end == -1) throw new IllegalArgumentException("Missing ';' in object type");
                    popOperand();
                    pos = end + 1;
                    break;
                case '[':
                    // consume array
                    while (descriptor.charAt(pos) == '[') pos++;
                    if (descriptor.charAt(pos) == 'L') {
                        int objEnd = descriptor.indexOf(';', pos);
                        if (objEnd == -1) throw new IllegalArgumentException("Missing ';' in array object type");
                        pos = objEnd + 1;
                    } else {
                        pos++;
                    }
                    popOperand();
                    break;
                default:
                    throw new IllegalArgumentException("Unknown type descriptor in method args: " + c);
            }
        }
        // Skip the ')' and return type (which we ignore)
    } catch (Exception e) {
        throw new IllegalArgumentException("Invalid descriptor: " + descriptor, e);
    }
}

@Override public void write(final byte b[], final int off, final int len) throws IOException {
    if (b == null) {
        throw new NullPointerException("b");
    }
    if (off < 0 || len < 0 || off > b.length - len) {
        throw new IndexOutOfBoundsException();
    }
    if (len == 0) {
        return;
    }
    int newCount = count + len;
    if (newCount > buf.length) {
        int growBy = Math.max(buf.length, len);
        byte[] newBuf = new byte[newCount + growBy];
        System.arraycopy(buf, 0, newBuf, 0, count);
        buf = newBuf;
    }
    System.arraycopy(b, off, buf, count, len);
    count = newCount;
}

