public static boolean containsAnyIgnoreCase(String str, List<String> searchStrArray) {
    // Return false if the input string or search array is null or empty
    if (str == null || searchStrArray == null || searchStrArray.isEmpty()) {
        return false;
    }
    // Build a set of all characters (in lower case) from the search strings
    java.util.Set<Character> searchSet = new java.util.HashSet<>();
    for (String s : searchStrArray) {
        if (s == null) continue;
        for (char ch : s.toLowerCase().toCharArray()) {
            searchSet.add(ch);
        }
    }
    // Iterate through each character of the input string (in lower case)
    for (char ch : str.toLowerCase().toCharArray()) {
        if (searchSet.contains(ch)) {
            return true;
        }
    }
    return false;
}

public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity <= 2) {
        return 2;
    }
    int n = desiredCapacity;
    if ((n & 1) == 0) {
        n++; // make odd
    }
    while (true) {
        boolean prime = true;
        int limit = (int) Math.sqrt(n);
        for (int i = 3; i <= limit; i += 2) {
            if (n % i == 0) {
                prime = false;
                break;
            }
        }
        if (prime) {
            return n;
        }
        n += 2; // next odd number
    }
}

