public final byte[] toByteArray(){
    try {
        // Prefer single content buffer if available
        if (content != null) {
            // If the buffer has remaining data, copy it; otherwise return the underlying array
            if (content.remaining() == content.capacity()) {
                return content.array();
            } else {
                byte[] result = new byte[content.remaining()];
                content.get(result);
                return result;
            }
        }
        // If there is a list of buffers, concatenate them
        if (buffers != null && !buffers.isEmpty()) {
            int total = 0;
            for (ByteBuffer buf : buffers) {
                if (buf != null) {
                    total += buf.remaining();
                }
            }
            byte[] result = new byte[total];
            int pos = 0;
            for (ByteBuffer buf : buffers) {
                if (buf != null) {
                    int len = buf.remaining();
                    buf.get(result, pos, len);
                    pos += len;
                }
            }
            return result;
        }
        // Fallback – return an empty array
        return new byte[0];
    } catch (Exception ex) {
        throw new RuntimeException("Failed to construct byte array from buffer(s)", ex);
    }
}

public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder(str.length());
    int len = str.length();
    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c != '\\') {
            sb.append(c);
            continue;
        }
        if (i == len - 1) {
            // Trailing backslash, append as is
            sb.append('\\');
            break;
        }
        i++;
        char next = str.charAt(i);
        switch (next) {
            case 'b':
                sb.append('\b');
                break;
            case 't':
                sb.append('\t');
                break;
            case 'n':
                sb.append('\n');
                break;
            case 'f':
                sb.append('\f');
                break;
            case 'r':
                sb.append('\r');
                break;
            case '\"':
                sb.append('\"');
                break;
            case '\'':
                sb.append('\'');
                break;
            case '\\':
                sb.append('\\');
                break;
            case 'u':
                if (i + 4 >= len) {
                    throw new Exception("Incomplete unicode escape sequence");
                }
                String hex = str.substring(i + 1, i + 5);
                try {
                    int code = Integer.parseInt(hex, 16);
                    sb.append((char) code);
                } catch (NumberFormatException e) {
                    throw new Exception("Invalid unicode escape: \\u" + hex, e);
                }
                i += 4;
                break;
            default:
                // Unknown escape sequence, retain the character
                sb.append(next);
                break;
        }
    }
    return sb.toString();
}

