protected int removeUnusedNodes() {
    int removedCount = 0;
    try {
        // Assume the Category tree root is stored in a field named 'root'.
        if (root == null) {
            return 0;
        }
        // Use a stack for depth‑first traversal.
        java.util.Deque<Category> stack = new java.util.ArrayDeque<>();
        stack.push(root);
        while (!stack.isEmpty()) {
            Category current = stack.pop();
            if (current == null) {
                continue;
            }
            // Push children onto the stack first.
            java.util.List<Category> children = current.getChildren();
            if (children != null) {
                for (Category child : children) {
                    stack.push(child);
                }
            }
            // If the current node is inactive, remove it from its parent.
            if (!current.isActive()) {
                Category parent = current.getParent();
                if (parent != null) {
                    parent.removeChild(current);
                    removedCount++;
                } else {
                    // Current node is the root; if it's inactive, drop the entire tree.
                    root = null;
                    removedCount++;
                    break;
                }
            }
        }
    } catch (Exception e) {
        // In case of any unexpected runtime issue, simply return the count so far.
    }
    return removedCount;
}

