private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (predicate == null) {
        throw new IllegalArgumentException("predicate must not be null");
    }
    if (start == null || stop == null) {
        throw new IllegalArgumentException("start and stop must not be null");
    }
    Node current = start;
    OuterFaceCirculator circ = new OuterFaceCirculator(current);
    while (true) {
        if (predicate.test(current)) {
            return circ;
        }
        if (current.equals(stop)) {
            break;
        }
        // Move to the next node in the specified direction
        current = current.getNext(dir); // Assumes Node has a getNext(int) method
        if (current == null) {
            break; // Defensive: exit if traversal cannot continue
        }
        circ = new OuterFaceCirculator(current);
    }
    return circ;
}

