protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    if (tour == null || tour.isEmpty() || graph == null) {
        return null;
    }
    Set<E> remaining = new LinkedHashSet<>(tour);
    List<E> orderedEdges = new ArrayList<>(tour.size());
    List<V> vertices = new ArrayList<>(tour.size() + 1);

    // Start with an arbitrary edge
    Iterator<E> it = remaining.iterator();
    if (!it.hasNext()) {
        return null;
    }
    E first = it.next();
    it.remove();
    V source = graph.getEdgeSource(first);
    V target = graph.getEdgeTarget(first);
    vertices.add(source);
    vertices.add(target);
    orderedEdges.add(first);
    V current = target;

    while (!remaining.isEmpty()) {
        boolean found = false;
        Iterator<E> rIt = remaining.iterator();
        while (rIt.hasNext()) {
            E e = rIt.next();
            V s = graph.getEdgeSource(e);
            V t = graph.getEdgeTarget(e);
            if (s.equals(current)) {
                vertices.add(t);
                orderedEdges.add(e);
                current = t;
                rIt.remove();
                found = true;
                break;
            } else if (t.equals(current)) {
                vertices.add(s);
                orderedEdges.add(e);
                current = s;
                rIt.remove();
                found = true;
                break;
            }
        }
        if (!found) {
            // The set does not form a contiguous tour
            return null;
        }
    }

    return new Path<>(graph, vertices, orderedEdges);
}

