private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    if (bucketsByLabel == null || labels == null) {
        throw new IllegalArgumentException("Buckets and labels must not be null.");
    }
    if (minLabel < 0 || minLabel >= bucketsByLabel.size()) {
        throw new IllegalArgumentException("minLabel out of bounds: " + minLabel);
    }
    // No operation needed if source and destination are the same bucket
    if (minLabel == 0) {
        return;
    }
    Set<Integer> source = bucketsByLabel.get(minLabel);
    if (source == null || source.isEmpty()) {
        return; // nothing to move
    }
    Set<Integer> destination = bucketsByLabel.get(0);
    if (destination == null) {
        throw new IllegalStateException("Destination bucket 0 is null.");
    }
    for (Integer vertex : source) {
        destination.add(vertex);
        labels.set(vertex, 0);
    }
    source.clear(); // clear the moved bucket
}

