public static String stripFilenameExtension(String path) {
    if (path == null) {
        return null;
    }
    // Find last file separator (handles both Unix '/' and Windows '\\')
    int lastSeparatorIndex = Math.max(path.lastIndexOf('/'), path.lastIndexOf('\\'));
    int dotIndex = path.lastIndexOf('.');
    // If there is no dot after the last separator, there is no extension
    if (dotIndex <= lastSeparatorIndex) {
        return null;
    }
    // Strip everything from the dot onward
    return path.substring(0, dotIndex);
}

