private String parseToken(final char[] terminators) {
    // Ensure terminators array is not null to avoid NullPointerException.
    if (terminators == null) {
        throw new IllegalArgumentException("terminators array cannot be null");
    }
    // Validate that terminators are not empty; empty array means nothing ever terminates.
    if (terminators.length == 0) {
        throw new IllegalArgumentException("terminators array cannot be empty");
    }

    // Assume the source string and current position are maintained by the class
    // (for example: private String source; private int index;).
    // If those fields are not present, this method will not compile.
    if (source == null) {
        throw new IllegalStateException("Source string not initialized");
    }

    // Record the starting position of the token
    int start = index;

    // Scan forward until a terminator or the end of the source is reached
    while (index < source.length()) {
        char current = source.charAt(index);
        boolean isTerminator = false;
        for (char term : terminators) {
            if (current == term) {
                isTerminator = true;
                break;
            }
        }
        if (isTerminator) {
            // Stop before the terminator
            break;
        }
        index++;
    }

    // Return the extracted token
    return source.substring(start, index);
}

