private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds){
    if (bounds == null || bounds.isEmpty()){
        return new Pair<>(Collections.emptyList(), 0L);
    }
    int n = bounds.size();
    List<Integer> suffixSum = new ArrayList<>(n);
    for (int i = 0; i < n; i++){
        suffixSum.add(0);
    }
    long totalSum = 0L;
    long runningSum = 0L;
    for (int i = n - 1; i >= 0; i--){
        int value = bounds.get(i);
        runningSum += value;
        suffixSum.set(i, (int) runningSum);
        totalSum += value;
    }
    return new Pair<>(suffixSum, totalSum);
}

public static final <V> void reverse(V[] arr,int from,int to){
    if (arr == null) {
        throw new IllegalArgumentException("Array must not be null");
    }
    int length = arr.length;
    if (from < 0 || to >= length) {
        throw new IndexOutOfBoundsException("Index out of bounds");
    }
    if (from > to) {
        throw new IllegalArgumentException("from index must be <= to index");
    }
    while (from < to) {
        V temp = arr[from];
        arr[from] = arr[to];
        arr[to] = temp;
        from++;
        to--;
    }
}

