public void putAllWriteable(BeanMap map){
    if (map == null) {
        return;
    }
    Object srcBean = map.getBean();
    Object tgtBean = this.getBean();
    if (srcBean == null || tgtBean == null) {
        return;
    }
    try {
        java.beans.PropertyDescriptor[] pds = java.beans.Introspector.getBeanInfo(srcBean.getClass()).getPropertyDescriptors();
        for (java.beans.PropertyDescriptor pd : pds) {
            String name = pd.getName();
            if ("class".equals(name)) {
                continue;
            }
            java.lang.reflect.Method readMethod = pd.getReadMethod();
            java.lang.reflect.Method writeMethod = pd.getWriteMethod();
            if (readMethod != null && writeMethod != null) {
                Object value = readMethod.invoke(srcBean);
                writeMethod.invoke(tgtBean, value);
            }
        }
    } catch (Exception e) {
        // Ignore or log as per application's logging policy
    }
}

