private List<Pair<List<Pair<Integer,Integer>>, E>> computeGlobalSeparatorList() {
    try {
        if (graph == null) {
            return Collections.emptyList();
        }
        List<Pair<List<Pair<Integer,Integer>>, E>> globalList = new ArrayList<>();
        for (E edge : graph.getEdges()) {
            if (edge == null) {
                continue;
            }
            List<List<Pair<Integer,Integer>>> minimalSeparators = computeMinimalSeparators(edge);
            if (minimalSeparators == null) {
                continue;
            }
            for (List<Pair<Integer,Integer>> separator : minimalSeparators) {
                if (separator == null) {
                    continue;
                }
                globalList.add(new Pair<>(separator, edge));
            }
        }
        return globalList;
    } catch (Exception e) {
        // Log the exception if a logger is available
        if (LOG != null) {
            LOG.warning("Failed to compute global separator list: " + e.getMessage());
        }
        return new ArrayList<>();
    }
}

