        task.run();
    } else {
        javax.swing.SwingUtilities.invokeLater(task);
    }
}

public ByteVector putInt(final int intValue){
    if (buffer == null){
        buffer = new byte[4];
    }
    int required = position + 4;
    if (required > buffer.length){
        int newCapacity = Math.max(buffer.length * 2, required);
        byte[] newBuf = new byte[newCapacity];
        System.arraycopy(buffer, 0, newBuf, 0, buffer.length);
        buffer = newBuf;
    }
    buffer[position]     = (byte)(intValue >>> 24);
    buffer[position + 1] = (byte)(intValue >>> 16);
    buffer[position + 2] = (byte)(intValue >>> 8);
    buffer[position + 3] = (byte)(intValue);
    position += 4;
    return this;
}

