public void abbreviate(final int nameStart, final StringBuffer buf){
    if (buf == null || nameStart < 0) return;
    int length = buf.length();
    if (nameStart >= length) return;
    StringBuilder abbr = new StringBuilder();
    boolean inSegment = false;
    for (int i = nameStart; i < length; i++) {
        char ch = buf.charAt(i);
        if (ch == '.') {
            abbr.append('.');
            inSegment = false;
        } else {
            if (!inSegment) {
                abbr.append(ch);
                inSegment = true;
            } // else skip remaining characters of the current segment
        }
    }
    buf.append(abbr);
}

