private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (graph == null || vertices == null) {
        return false;
    }
    int size = vertices.size();
    if (size <= 1) {
        // A single vertex (or empty set) is trivially a clique
        return true;
    }
    // Convert to list for indexed access
    List<V> vertexList = new ArrayList<>(vertices);
    for (int i = 0; i < vertexList.size(); i++) {
        V u = vertexList.get(i);
        for (int j = i + 1; j < vertexList.size(); j++) {
            V v = vertexList.get(j);
            // Check that an edge exists between each pair
            if (!graph.containsEdge(u, v)) {
                return false;
            }
        }
    }
    return true;
}

private List<Integer> computeLowerBounds(List<K> keys){
    if (keys == null) {
        throw new IllegalArgumentException("keys must not be null");
    }
    List<Integer> result = new ArrayList<>(keys.size());
    // Create a sorted copy of the keys
    List<K> sorted = new ArrayList<>(keys);
    try {
        Collections.sort((List)sorted);
    } catch (ClassCastException e) {
        throw new IllegalArgumentException("elements must be comparable", e);
    }
    for (K key : keys) {
        if (key == null) {
            result.add(-1);
            continue;
        }
        int idx;
        try {
            idx = Collections.binarySearch((List)sorted, key);
        } catch (ClassCastException e) {
            result.add(-1);
            continue;
        }
        int lowerIdx;
        if (idx >= 0) {
            lowerIdx = idx;
        } else {
            int insertionPoint = -(idx) - 1;
            lowerIdx = insertionPoint - 1;
        }
        result.add(lowerIdx);
    }
    return result;
}

private void pop(final String descriptor){
    int slotsToPop = 0;
    try {
        int idx = 0;
        if (descriptor.charAt(0) == '(') { // method descriptor
            idx = 1;
            while (descriptor.charAt(idx) != ')') {
                char typeChar = descriptor.charAt(idx);
                int width;
                // Determine width for current argument type
                if (typeChar == 'J' || typeChar == 'D') {
                    width = 2;
                } else {
                    width = 1;
                }
                // Advance idx past the whole type representation
                if (typeChar == '[') {
                    // consume all '[' characters
                    while (descriptor.charAt(idx) == '[') idx++;
                    // if it is a reference type, skip until ';'
                    if (descriptor.charAt(idx) == 'L') {
                        idx = descriptor.indexOf(';', idx);
                    }
                } else if (typeChar == 'L') {
                    idx = descriptor.indexOf(';', idx);
                }
                // Move past the representation
                idx++;
                slotsToPop += width;
            }
            // Skip the return type
        } else { // single type descriptor
            char typeChar = descriptor.charAt(0);
            if (typeChar == 'J' || typeChar == 'D') {
                slotsToPop = 2;
            } else if (typeChar == 'V') {
                slotsToPop = 0;
            } else {
                slotsToPop = 1;
            }
        }
    } catch (StringIndexOutOfBoundsException | NullPointerException ex) {
        throw new IllegalArgumentException("Malformed descriptor: " + descriptor, ex);
    }
    for (int i = 0; i < slotsToPop; i++) {
        outputFrame.pop();
    }
}

