public static String applyRelativePath(String path,String relativePath){
    if (path == null) {
        throw new IllegalArgumentException("path cannot be null");
    }
    if (relativePath == null) {
        throw new IllegalArgumentException("relativePath cannot be null");
    }
    // An absolute relativePath should be treated as an error
    if (relativePath.startsWith("/")) {
        throw new IllegalArgumentException("relativePath must be relative, not absolute");
    }
    // Determine base directory from the path
    String base;
    if (path.endsWith("/")) {
        base = path;
    } else {
        int idx = path.lastIndexOf('/');
        if (idx >= 0) {
            base = path.substring(0, idx + 1);
        } else {
            base = "";
        }
    }
    // Split base and relative components
    java.util.ArrayList<String> stack = new java.util.ArrayList<>();
    if (!base.isEmpty()) {
        String[] baseParts = base.split("/");
        for (String p : baseParts) {
            if (p.isEmpty() || p.equals(".")) continue;
            if (p.equals("..")) {
                if (!stack.isEmpty()) stack.remove(stack.size() - 1);
            } else {
                stack.add(p);
            }
        }
    }
    String[] relParts = relativePath.split("/");
    for (String part : relParts) {
        if (part.isEmpty() || part.equals(".")) continue;
        if (part.equals("..")) {
            if (!stack.isEmpty() && !stack.get(stack.size() - 1).equals("..")) {
                stack.remove(stack.size() - 1);
            } else {
                stack.add("..");
            }
        } else {
            stack.add(part);
        }
    }
    // Build the resulting path
    StringBuilder result = new StringBuilder();
    if (path.startsWith("/") || base.startsWith("/")) {
        result.append("/");
    }
    for (int i = 0; i < stack.size(); i++) {
        if (i > 0) result.append("/");
        result.append(stack.get(i));
    }
    return result.toString();
}

