static String[] toNoNullStringArray(Object[] array) {
    if (array == null) {
        return null;
    }
    int nonNullCount = 0;
    for (Object obj : array) {
        if (obj != null) {
            nonNullCount++;
        }
    }
    if (nonNullCount == array.length) {
        // All elements are non‑null; attempt a safe cast
        try {
            return (String[]) array;
        } catch (ClassCastException ignored) {
            // fall through to create a copy
        }
    }
    String[] result = new String[nonNullCount];
    int idx = 0;
    for (Object obj : array) {
        if (obj != null) {
            result[idx++] = (obj instanceof String) ? (String) obj : obj.toString();
        }
    }
    return result;
}

