private void checkIfPackedField() throws IOException {
    // Check the wire type of the most recently read tag.
    // Length-delimited wire type (value 2) indicates a packed field.
    int wireType = lastTag & 0x7;
    if (wireType == 2) {
        // Read the length of the packed data (varint32).
        int packedLength = readRawVarint32();
        // Mark that we are now inside a packed field.
        isPackedField = true;
        // Set a limit for the packed data so subsequent reads
        // are constrained to the packed block.
        packedFieldLimit = input.limit() + packedLength;
    }
}

