    }
    this.buffer[this.pos++] = (byte) byteValue1;
    this.buffer[this.pos++] = (byte) byteValue2;
    return this;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    if (file == null || !file.exists() || !file.isFile()) {
        throw new FileNotFoundException("File not found: " + file);
    }
    if (timeRanges == null || timeRanges.isEmpty()) {
        return Collections.emptyList();
    }
    List<ThreadSnapshot> result = new ArrayList<>();
    try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(file))) {
        Object obj = ois.readObject();
        if (!(obj instanceof List)) {
            throw new IOException("Invalid file format: expected List<ThreadSnapshot>");
        }
        List<?> rawList = (List<?>) obj;
        for (Object element : rawList) {
            if (!(element instanceof ThreadSnapshot)) {
                continue;
            }
            ThreadSnapshot snapshot = (ThreadSnapshot) element;
            long snapshotTime = snapshot.getTimestamp(); // adjust method name if different
            for (ProfileAnalyzeTimeRange range : timeRanges) {
                if (snapshotTime >= range.getStartTime() && snapshotTime <= range.getEndTime()) {
                    result.add(snapshot);
                    break;
                }
            }
        }
    } catch (ClassNotFoundException e) {
        throw new IOException("Could not deserialize ThreadSnapshot objects", e);
    }
    return result;
}
